INSERT INTO puzzle_collections VALUES ('steps-2-workbook', 'Steps 2 Workbook', 'Tactical exercises organized in the same learning sequence as the workbook.', 0);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'step-1-review', 'Step 1 Review', 'Review activity of the pieces with mixed exercises from Step 1.', 'Pages 3–4', 0);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'double-attack-queen', 'Double Attack: Queen', 'Place or move the queen to create a double attack.', 'Pages 6–14', 1);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'the-pin', 'The Pin', 'Recognize pins and find moves that set them up.', 'Pages 15–19', 2);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'eliminating-the-defence', 'Eliminating the Defence', 'Win material by capturing, chasing away, or luring away a defender.', 'Pages 20–24', 3);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'opening-principles', 'Opening Principles', 'Practice the three golden opening rules.', 'Pages 25–26', 4);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'mixed-review-1', 'Mixed Review I', 'Identify the right idea without being told which tactic to use.', 'Pages 27–30', 5);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'mate-in-two', 'Mate in Two', 'Compose and calculate checkmate in two moves.', 'Pages 31–35 and 38', 6);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'double-attack-knight', 'Double Attack: Knight', 'Find knight moves that attack two targets at once.', 'Pages 36–37', 7);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'mixed-review-2', 'Mixed Review II', 'A second set of mixed tactical exercises.', 'Pages 39–40', 8);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'double-attack-other-pieces', 'Double Attack: Other Pieces', 'Use rooks, bishops, pawns, kings, and cooperating pieces.', 'Pages 41–43', 9);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'discovered-attack', 'Discovered Attack', 'Open a line for one piece while the moving piece creates another threat.', 'Pages 44–48', 10);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'defending-against-mate', 'Defending Against Mate', 'Recognize mating threats and choose an effective defence.', 'Pages 49–51', 11);
INSERT INTO puzzle_sections VALUES ('steps-2-workbook', 'notation-and-final-review', 'Notation and Final Review', 'Practice short notation and finish with mixed review exercises.', 'Pages 52–56', 12);
